#!/bin/sh
# set -e

# Treat whatever directory we're in when we run this script as the repo root
REPO_ROOT="$(pwd)"
TOP_FILENAME="core_top"

# cleanup
rm -rf obj_dir
rm -f *.vcd

# run Verilator to translate Verilog into C++, including C++ testbench
VERILOG_SOURCES=$(find "${REPO_ROOT}/rtl" -maxdepth 2 -name '*.sv' -print | tr '\n' ' ')
verilator -Wall --Wno-UNUSED --cc --trace --top-module ${TOP_FILENAME} ${VERILOG_SOURCES} \
    --exe "${REPO_ROOT}/tb/top_tb.cpp"

# build C++ project via make automatically generated by Verilator
make -j -C "${REPO_ROOT}/obj_dir/" -f V${TOP_FILENAME}.mk V${TOP_FILENAME}
# run executable simulation file
echo "\nRunning simulation"
"${REPO_ROOT}/obj_dir/V${TOP_FILENAME}"
echo "\nSimulation completed"
